 std::atomic<bool>stop{false};std::atomic<uint64_t>frames{0},blocks{0};std::atomic<double>maxDryError{0},rms{0};std::mutex errorMutex;String threadError;std::thread audio([&]{try{AudioBuffer<float>b(2,256);MidiBuffer midi;Clock clock;auto start=std::chrono::steady_clock::now();uint64_t f=0;double energy=0;uint64_t samples=0;while(!stop){for(int ch=0;ch<2;++ch)for(int i=0;i<256;++i)b.setSample(ch,i,input(f+i,ch));auto before=p.captureResponseState();inAudio=true;p.processBlock(b,midi);inAudio=false;ensure(audioNews==0,"Audio callback C++ operator new allocation");auto s=p.captureResponseState();for(int ch=0;ch<2;++ch)for(int i=0;i<256;++i){const double x=b.getSample(ch,i);ensure(std::isfinite(x),"Non-finite audio output");energy+=x*x;++samples;if(before.isSteady()&&before.appliedDegree==0&&s.isSteady()&&s.appliedDegree==0&&f+i>=(uint64_t)s.latencySamples){double err=std::abs(x-input(f+i-s.latencySamples,ch));if(err>maxDryError.load())maxDryError=err;ensure(err<1e-6,"Settled 0% dry path violates existing1e-6 exact-delay limit");}}f+=256;frames=f;++blocks;if(samples>=96000){rms=std::sqrt(energy/samples);energy=0;samples=0;}clock.wait(start+std::chrono::microseconds((int64)(f*1000000/48000)));}}catch(const std::exception&e){inAudio=false;{std::lock_guard<std::mutex>lock(errorMutex);threadError=e.what();}stop=true;}});
 int lastProfile=-1,lastBpm=-1;uint64_t renders=0;double nextRender=0,nextShot=0,profileAt=-100;int requested=0;bool tempo=false,profileConfirmed=false;double lastValidAt=0,invalidAt=-1,maxInvalidMs=0,maxConfirmMs=0,lastEventFlush=0;uint64_t invalidCount=0,confirmedRequests=0;String profileEvents;
