  put(evidence.state,"audioFrames",(int64)frames.load());put(evidence.state,"audioBlocks",(int64)blocks.load());put(evidence.state,"nativeRenders",(int64)renders);put(evidence.state,"outputRms",rms.load());put(evidence.state,"maxSettledDryError",maxDryError.load());put(evidence.state,"callbackCppNew",(int64)audioNews.load());put(evidence.state,"activeProfile",s.activeProfile);put(evidence.state,"appliedDegree",s.appliedDegree);put(evidence.state,"hostBpm",p.getHostBpmSnapshot().bpm);evidence.tick();Thread::sleep(5);
